type journalWhere[Q psql.Filterable] struct {
	cols           journalColumns
	ID             psql.WhereMod[Q, uuid.UUID]
	HouseholdID    psql.WhereMod[Q, uuid.UUID]
	SourceKind     psql.WhereMod[Q, string]
	SourceID       psql.WhereMod[Q, uuid.UUID]
	IdempotencyKey psql.WhereMod[Q, string]
	OccurredAt     psql.WhereMod[Q, time.Time]
	CreatedBy      psql.WhereMod[Q, uuid.UUID]
	CreatedAt      psql.WhereMod[Q, time.Time]
	R              journalWhereR[Q]
}

func (journalWhere[Q]) AliasedAs(alias string) journalWhere[Q] {
	return buildJournalWhere[Q](buildJournalColumns(alias))
}

func buildJournalWhere[Q psql.Filterable](cols journalColumns) journalWhere[Q] {
	return journalWhere[Q]{
		cols:           cols,
		ID:             psql.Where[Q, uuid.UUID](cols.ID.Expression),
		HouseholdID:    psql.Where[Q, uuid.UUID](cols.HouseholdID.Expression),
		SourceKind:     psql.Where[Q, string](cols.SourceKind.Expression),
		SourceID:       psql.Where[Q, uuid.UUID](cols.SourceID.Expression),
		IdempotencyKey: psql.Where[Q, string](cols.IdempotencyKey.Expression),
		OccurredAt:     psql.Where[Q, time.Time](cols.OccurredAt.Expression),
		CreatedBy:      psql.Where[Q, uuid.UUID](cols.CreatedBy.Expression),
		CreatedAt:      psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		R:              journalWhereR[Q]{cols: cols},
	}
}

// journalWhereR holds the relationship-based filters of
// journalWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type journalWhereR[Q psql.Filterable] struct {
	cols journalColumns
}

// HasAccountIncome filters parents that have a matching AccountIncome using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to AccountIncomes).
func (w journalWhereR[Q]) HasAccountIncome(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(AccountIncomes.NameExpr()),
		sm.Where(AccountIncomes.Columns.JournalID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasAccountMovement filters parents that have a matching AccountMovement using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
