// NULL-tolerant scan buffer for journalScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type journalPreloadBuf struct {
	ID             sql.Null[uuid.UUID]
	HouseholdID    sql.Null[uuid.UUID]
	SourceKind     sql.Null[string]
	SourceID       sql.Null[uuid.UUID]
	IdempotencyKey sql.Null[string]
	OccurredAt     sql.Null[time.Time]
	CreatedBy      sql.Null[uuid.UUID]
	CreatedAt      sql.Null[time.Time]
}

// journalScanMapperNullable maps the preloaded journal
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func journalScanMapperNullable(prefix string) scan.Mapper[*Journal] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Journal, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *journalPreloadBuf) any
		}
		targets := make([]target, 0, 8)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *journalPreloadBuf) any { return &b.ID }})
			case "household_id":
				targets = append(targets, target{i, func(b *journalPreloadBuf) any { return &b.HouseholdID }})
			case "source_kind":
				targets = append(targets, target{i, func(b *journalPreloadBuf) any { return &b.SourceKind }})
			case "source_id":
				targets = append(targets, target{i, func(b *journalPreloadBuf) any { return &b.SourceID }})
			case "idempotency_key":
				targets = append(targets, target{i, func(b *journalPreloadBuf) any { return &b.IdempotencyKey }})
			case "occurred_at":
				targets = append(targets, target{i, func(b *journalPreloadBuf) any { return &b.OccurredAt }})
			case "created_by":
				targets = append(targets, target{i, func(b *journalPreloadBuf) any { return &b.CreatedBy }})
			case "created_at":
				targets = append(targets, target{i, func(b *journalPreloadBuf) any { return &b.CreatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(journalPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Journal, error) {
				buf := link.(*journalPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.Valid) &&
					!(buf.HouseholdID.Valid) &&
					!(buf.SourceKind.Valid) &&
					!(buf.SourceID.Valid) &&
					!(buf.IdempotencyKey.Valid) &&
					!(buf.OccurredAt.Valid) &&
					!(buf.CreatedBy.Valid) &&
					!(buf.CreatedAt.Valid) {
					return nil, nil
				}

				o := new(Journal)
				if buf.ID.Valid {
					o.ID = buf.ID.V
				}
				if buf.HouseholdID.Valid {
					o.HouseholdID = buf.HouseholdID.V
				}
				if buf.SourceKind.Valid {
					o.SourceKind = buf.SourceKind.V
				}
				if buf.SourceID.Valid {
					o.SourceID = buf.SourceID.V
				}
				if buf.IdempotencyKey.Valid {
					o.IdempotencyKey = buf.IdempotencyKey.V
				}
				if buf.OccurredAt.Valid {
					o.OccurredAt = buf.OccurredAt.V
				}
				if buf.CreatedBy.Valid {
					o.CreatedBy = buf.CreatedBy.V
				}
				if buf.CreatedAt.Valid {
					o.CreatedAt = buf.CreatedAt.V
				}
				return o, nil
			}
	}
}

func (o *Journal) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "AccountIncome":
		rel, ok := retrieved.(*AccountIncome)
		if !ok {
			return fmt.Errorf("journal cannot load %T as %q", retrieved, name)
		}

		o.R.AccountIncome = rel
		o.R.Loaded.AccountIncome = true

		if rel != nil {
			rel.R.Journal = o
			rel.R.Loaded.Journal = true
		}
		return nil
	case "AccountMovement":
		rel, ok := retrieved.(*AccountMovement)
		if !ok {
			return fmt.Errorf("journal cannot load %T as %q", retrieved, name)
		}

		o.R.AccountMovement = rel
		o.R.Loaded.AccountMovement = true

		if rel != nil {
			rel.R.Journal = o
			rel.R.Loaded.Journal = true
		}
		return nil
	case "Corrections":
		rels, ok := retrieved.(CorrectionSlice)
		if !ok {
			return fmt.Errorf("journal cannot load %T as %q", retrieved, name)
		}

		o.R.Corrections = rels
		o.R.Loaded.Corrections = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Journal = o
				rel.R.Loaded.Journal = true
			}
		}
		return nil
	case "JournalEntries":
		rels, ok := retrieved.(JournalEntrySlice)
		if !ok {
			return fmt.Errorf("journal cannot load %T as %q", retrieved, name)
		}

		o.R.JournalEntries = rels
		o.R.Loaded.JournalEntries = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Journal = o
				rel.R.Loaded.Journal = true
			}
		}
		return nil
	case "CreatedByMember":
		rel, ok := retrieved.(*Member)
		if !ok {
			return fmt.Errorf("journal cannot load %T as %q", retrieved, name)
		}

		o.R.CreatedByMember = rel
		o.R.Loaded.CreatedByMember = true

		if rel != nil {
			rel.R.CreatedByJournals = JournalSlice{o}
		}
		return nil
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("journal cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.Journals = JournalSlice{o}
		}
		return nil
	case "LedgerEntries":
		rels, ok := retrieved.(LedgerEntrySlice)
		if !ok {
			return fmt.Errorf("journal cannot load %T as %q", retrieved, name)
		}

		o.R.LedgerEntries = rels
		o.R.Loaded.LedgerEntries = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Journal = o
				rel.R.Loaded.Journal = true
			}
		}
		return nil
	default:
		return fmt.Errorf("journal has no relationship %q", name)
	}
}

type journalPreloader struct {
	AccountIncome   func(...psql.PreloadOption) psql.Preloader
	AccountMovement func(...psql.PreloadOption) psql.Preloader
	CreatedByMember func(...psql.PreloadOption) psql.Preloader
	Household       func(...psql.PreloadOption) psql.Preloader
}

func buildJournalPreloader() journalPreloader {
	return journalPreloader{
		AccountIncome: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*AccountIncome, AccountIncomeSlice](psql.PreloadRel{
				Name: "AccountIncome",
				Sides: []psql.PreloadSide{
					{
						From:        Journals,
						To:          AccountIncomes,
						FromColumns: []string{"id"},
						ToColumns:   []string{"journal_id"},
					},
				},
			}, AccountIncomes.Columns.Names(), accountIncomeScanMapperNullable, opts...)
		},
		AccountMovement: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*AccountMovement, AccountMovementSlice](psql.PreloadRel{
				Name: "AccountMovement",
				Sides: []psql.PreloadSide{
					{
						From:        Journals,
						To:          AccountMovements,
						FromColumns: []string{"id"},
						ToColumns:   []string{"journal_id"},
					},
				},
			}, AccountMovements.Columns.Names(), accountMovementScanMapperNullable, opts...)
		},
		CreatedByMember: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Member, MemberSlice](psql.PreloadRel{
				Name: "CreatedByMember",
				Sides: []psql.PreloadSide{
					{
						From:        Journals,
						To:          Members,
						FromColumns: []string{"created_by"},
						ToColumns:   []string{"id"},
					},
				},
			}, Members.Columns.Names(), memberScanMapperNullable, opts...)
		},
		Household: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Household, HouseholdSlice](psql.PreloadRel{
				Name: "Household",
				Sides: []psql.PreloadSide{
					{
						From:        Journals,
						To:          Households,
						FromColumns: []string{"household_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Households.Columns.Names(), householdScanMapperNullable, opts...)
		},
	}
}

type journalThenLoader[Q orm.Loadable] struct {
	AccountIncome   func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	AccountMovement func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Corrections     func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	JournalEntries  func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	CreatedByMember func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Household       func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	LedgerEntries   func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildJournalThenLoader[Q orm.Loadable]() journalThenLoader[Q] {
	type AccountIncomeLoadInterface interface {
		LoadAccountIncome(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type AccountMovementLoadInterface interface {
		LoadAccountMovement(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type CorrectionsLoadInterface interface {
		LoadCorrections(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type JournalEntriesLoadInterface interface {
		LoadJournalEntries(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type CreatedByMemberLoadInterface interface {
		LoadCreatedByMember(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type HouseholdLoadInterface interface {
		LoadHousehold(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type LedgerEntriesLoadInterface interface {
		LoadLedgerEntries(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return journalThenLoader[Q]{
		AccountIncome: thenLoadBuilder[Q](
			"AccountIncome",
			func(ctx context.Context, exec bob.Executor, retrieved AccountIncomeLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadAccountIncome(ctx, exec, mods...)
			},
		),
		AccountMovement: thenLoadBuilder[Q](
			"AccountMovement",
			func(ctx context.Context, exec bob.Executor, retrieved AccountMovementLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadAccountMovement(ctx, exec, mods...)
			},
		),
		Corrections: thenLoadBuilder[Q](
			"Corrections",
			func(ctx context.Context, exec bob.Executor, retrieved CorrectionsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCorrections(ctx, exec, mods...)
			},
		),
		JournalEntries: thenLoadBuilder[Q](
			"JournalEntries",
			func(ctx context.Context, exec bob.Executor, retrieved JournalEntriesLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadJournalEntries(ctx, exec, mods...)
			},
		),
		CreatedByMember: thenLoadBuilder[Q](
			"CreatedByMember",
			func(ctx context.Context, exec bob.Executor, retrieved CreatedByMemberLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCreatedByMember(ctx, exec, mods...)
			},
		),
		Household: thenLoadBuilder[Q](
			"Household",
			func(ctx context.Context, exec bob.Executor, retrieved HouseholdLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadHousehold(ctx, exec, mods...)
			},
		),
		LedgerEntries: thenLoadBuilder[Q](
			"LedgerEntries",
			func(ctx context.Context, exec bob.Executor, retrieved LedgerEntriesLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadLedgerEntries(ctx, exec, mods...)
			},
		),
	}
}

// LoadAccountIncome loads the journal's AccountIncome into the .R struct
func (o *Journal) LoadAccountIncome(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.AccountIncome = nil
	o.R.Loaded.AccountIncome = false

	related, err := o.AccountIncome(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.Journal = o
	related.R.Loaded.Journal = true

	o.R.AccountIncome = related
	o.R.Loaded.AccountIncome = true
	return nil
}

// LoadAccountIncome loads the journal's AccountIncome into the .R struct
func (os JournalSlice) LoadAccountIncome(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	accountIncomes, err := os.AccountIncome(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.AccountIncome = nil
		o.R.Loaded.AccountIncome = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	journalByKey := make(map[uuid.UUID][]*Journal, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		journalByKey[o.ID] = append(journalByKey[o.ID], o)
	}

	for _, rel := range accountIncomes {

		owners, ok := journalByKey[rel.JournalID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.AccountIncome != nil {
				continue
			}

			rel.R.Journal = o
			rel.R.Loaded.Journal = true

			o.R.AccountIncome = rel

		}
	}

	return nil
}

