// LoadJournalEntries loads the journal's JournalEntries into the .R struct
func (os JournalSlice) LoadJournalEntries(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	journalEntries, err := os.JournalEntries(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.JournalEntries = nil
		o.R.Loaded.JournalEntries = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range journalEntries {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.ID == rel.JournalID) {
				continue
			}

			rel.R.Journal = o
			rel.R.Loaded.Journal = true

			o.R.JournalEntries = append(o.R.JournalEntries, rel)
		}
	}

	return nil
}

