type journalJoins[Q dialect.Joinable] struct {
	typ             string
	AccountIncome   modAs[Q, accountIncomeColumns]
	AccountMovement modAs[Q, accountMovementColumns]
	Corrections     modAs[Q, correctionColumns]
	JournalEntries  modAs[Q, journalEntryColumns]
	CreatedByMember modAs[Q, memberColumns]
	Household       modAs[Q, householdColumns]
	LedgerEntries   modAs[Q, ledgerEntryColumns]
}

func (j journalJoins[Q]) aliasedAs(alias string) journalJoins[Q] {
	return buildJournalJoins[Q](buildJournalColumns(alias), j.typ)
}

func buildJournalJoins[Q dialect.Joinable](cols journalColumns, typ string) journalJoins[Q] {
	return journalJoins[Q]{
		typ: typ,
		AccountIncome: modAs[Q, accountIncomeColumns]{
			c: AccountIncomes.Columns,
			f: func(to accountIncomeColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, AccountIncomes.NameExpr().As(to.Alias())).On(
						to.JournalID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		AccountMovement: modAs[Q, accountMovementColumns]{
			c: AccountMovements.Columns,
			f: func(to accountMovementColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, AccountMovements.NameExpr().As(to.Alias())).On(
						to.JournalID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Corrections: modAs[Q, correctionColumns]{
			c: Corrections.Columns,
			f: func(to correctionColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Corrections.NameExpr().As(to.Alias())).On(
						to.JournalID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		JournalEntries: modAs[Q, journalEntryColumns]{
			c: JournalEntries.Columns,
			f: func(to journalEntryColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, JournalEntries.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.JournalID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		CreatedByMember: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.CreatedBy),
					))
				}

				return mods
			},
		},
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
		LedgerEntries: modAs[Q, ledgerEntryColumns]{
			c: LedgerEntries.Columns,
			f: func(to ledgerEntryColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, LedgerEntries.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.JournalID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
